// Development helper: put a SYNTHETIC text item on the clipboard, optionally
// tagged with one of the excluded types. Never reads your clipboard.
//
//   osascript -l JavaScript scripts/write-test-item.js plain
//   osascript -l JavaScript scripts/write-test-item.js concealed
//
// Kinds: plain, transient, autogenerated, concealed, petermaurer, typeit4me, generated
// WARNING: this replaces whatever is on your clipboard.
ObjC.import('AppKit');

function run(argv) {
  const kinds = {
    plain: null,
    transient: 'org.nspasteboard.TransientType',
    autogenerated: 'org.nspasteboard.AutoGeneratedType',
    concealed: 'org.nspasteboard.ConcealedType',
    petermaurer: 'de.petermaurer.TransientPasteboardType',
    typeit4me: 'com.typeit4me.clipping',
    generated: 'Pasteboard generated type',
  };
  const kind = argv[0] || 'plain';
  if (!(kind in kinds)) {
    return 'unknown kind: ' + kind + '. Use one of: ' + Object.keys(kinds).join(', ');
  }
  const pb = $.NSPasteboard.generalPasteboard;
  if (kind === 'generated') {
    // 'Pasteboard generated type' is not a valid UTI, so the item API refuses it.
    // The legacy declareTypes path accepts arbitrary type strings.
    pb.declareTypesOwner($(['public.utf8-plain-text', kinds[kind]]), $());
    pb.setStringForType($('clipshelf synthetic item (generated)'), $('public.utf8-plain-text'));
    return 'wrote synthetic item: generated (legacy declareTypes)';
  }
  pb.clearContents;
  const item = $.NSPasteboardItem.alloc.init;
  const text = 'clipshelf synthetic item (' + kind + ')';
  item.setStringForType($(text), $('public.utf8-plain-text'));
  if (kinds[kind]) {
    item.setDataForType($.NSData.data, $(kinds[kind]));
  }
  pb.writeObjects($([item]));
  return 'wrote synthetic item: ' + kind;
}
